export const gcpSystemDesignCases = [
  {
    "id": "method",
    "title": "The method",
    "html": "<section class=\"casebook-section\" id=\"case-method\">\n      <div class=\"section-head\"><div class=\"num\">00</div><div><h2>The six-step interview method</h2><p>Spend roughly 5, 5, 5, 5, 15, and 10 minutes across these phases in a 45-minute round.</p></div></div>\n      <div class=\"method\">\n        <div><span>01</span><strong>Clarify</strong><p>Users, outcomes, scope, non-goals, source of truth.</p></div>\n        <div><span>02</span><strong>Quantify</strong><p>Throughput, volume, retention, concurrency, growth.</p></div>\n        <div><span>03</span><strong>Guarantees</strong><p>Latency, correctness, availability, RPO/RTO.</p></div>\n        <div><span>04</span><strong>Model</strong><p>Events, keys, grain, schema, ownership, evolution.</p></div>\n        <div><span>05</span><strong>Design</strong><p>Ingest, process, store, serve, orchestrate.</p></div>\n        <div><span>06</span><strong>Operate</strong><p>Failure, replay, security, SLO, cost, rollout.</p></div>\n      </div>\n      <div class=\"callout\"><strong>Interview behavior:</strong> state assumptions and make progress. “I’ll assume 2 million events/sec peak and a two-minute freshness SLO; I can revise if you want a different scale.”</div>\n    </section>"
  },
  {
    "id": "clickstream",
    "title": "Clickstream analytics",
    "html": "<section class=\"casebook-section\" id=\"case-clickstream\">\n      <div class=\"section-head\"><div class=\"num\">01</div><div><h2>High-volume clickstream analytics</h2><p>Design ingestion and near-real-time analytics for product events from web and mobile clients.</p></div></div>\n      <div class=\"brief\"><article class=\"card\"><div class=\"tags\"><span class=\"tag\">Streaming</span><span class=\"tag amber\">BigQuery</span></div><p class=\"question\">“Design a platform for product analytics at millions of events per second.”</p><p>Consumers need live operational funnels plus historical behavioral analysis.</p></article><article class=\"card\"><h3>Architect’s thesis</h3><p>Separate durable event capture, replayable raw history, streaming aggregates, and analyst-serving workloads. Make consent and schema governance first-class.</p></article></div>\n      <div class=\"skeleton\">\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">01</span><h3>Clarify</h3></div><ul><li>Events: page views, clicks, sessions, experiments.</li><li>Consumers: product dashboards, anomaly alerts, analysts.</li><li>Is every raw event queryable? Are bots excluded?</li><li>Consent and deletion policy by region/user.</li><li>Non-goal: synchronous product decisions.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">02</span><h3>Quantify</h3></div><ul><li><span class=\"metric\">500k events/s average; 2M peak.</span></li><li>~1 KB/event → ~43 TB/day raw average.</li><li>90-day hot raw; 2-year aggregates.</li><li>10k dashboard queries/day; 500 concurrent analysts.</li><li>3× growth headroom.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">03</span><h3>Guarantees</h3></div><ul><li>Dashboard freshness: p95 &lt; 2 minutes.</li><li>Raw durability: no acknowledged event loss.</li><li>At-least-once capture; idempotent downstream effect.</li><li>Events may arrive 24h late; correct daily results within 48h.</li><li>Serving availability: 99.9%; RPO &lt; 5 min.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">04</span><h3>Model</h3></div><ul><li>Envelope: <code>event_id</code>, user/device, event time, ingest time.</li><li>Event name, schema version, source/app version, consent state.</li><li>Typed payload plus controlled extension attributes.</li><li>Partition raw by event date; cluster by event/user.</li><li>Session/funnel tables are derived products, never source of truth.</li></ul></article>\n        <article class=\"phase full\"><div class=\"phase-head\"><span class=\"badge\">05</span><h3>Design</h3></div>\n          <div class=\"diagram\" role=\"img\" aria-label=\"Clickstream system design\"><div class=\"diagram-title\">Capture → process → preserve → serve</div><div class=\"flow\"><div class=\"node source\">Web + mobile SDK<small>batch, retry, event ID</small></div><div class=\"arrow\">→</div><div class=\"node\">Pub/Sub<small>durable fan-out</small></div><div class=\"arrow\">→</div><div class=\"node\">Dataflow<small>validate, dedupe, window</small></div><div class=\"arrow\">→</div><div class=\"node store\">BigQuery raw + aggregate<small>partition + cluster</small></div><div class=\"arrow\">→</div><div class=\"node serve\">BI / alerts / analysts<small>isolated workloads</small></div></div></div>\n          <ul><li>Client batches with stable IDs; edge/API authenticates, rejects oversize payloads, and rate-limits abuse.</li><li>Pub/Sub decouples producers and supports separate quality, fraud/bot, and analytics subscriptions.</li><li>Dataflow validates contracts, routes invalid events, applies event-time windows, and writes raw plus low-latency aggregates.</li><li>BigQuery raw tables preserve accepted events; Dataform builds governed marts. Cloud Storage can hold a lower-cost archive if policy requires.</li></ul>\n        </article>\n        <article class=\"phase full operate\"><div class=\"phase-head\"><span class=\"badge\">06</span><h3>Operate</h3></div><ul><li><strong>Failure:</strong> monitor publish errors, oldest unacked age, watermark lag, invalid-event rate, BigQuery write errors.</li><li><strong>Hot keys:</strong> avoid global windows and low-cardinality keys; shard heavy aggregations, then combine.</li><li><strong>Replay:</strong> reprocess raw by date into versioned outputs; atomically switch views after reconciliation.</li><li><strong>Security:</strong> pseudonymous IDs, consent enforcement, least privilege, regional datasets, retention/deletion jobs.</li><li><strong>Cost:</strong> event volume, Dataflow state/shuffle, BigQuery scans. Preaggregate common dashboards and enforce partition filters.</li><li><strong>Rollout:</strong> shadow one app, compare SDK counters to raw ingestion, then expand by platform and region.</li></ul></article>\n      </div>\n      <div class=\"decision\"><article class=\"card\"><h3>Why Pub/Sub?</h3><p>Managed fan-out and elastic ingestion. Choose Kafka when partition control, Kafka APIs, or log-oriented replay requirements dominate.</p></article><article class=\"card\"><h3>Why raw + aggregate?</h3><p>Raw enables correction and new questions; aggregates protect latency and cost for predictable dashboards.</p></article><article class=\"card\"><h3>Biggest trap</h3><p>Calling delivery “exactly once” while clients retry with new IDs or downstream side effects are non-idempotent.</p></article></div>\n      <div class=\"probes\"><strong>Follow-ups:</strong> Handle a celebrity-driven 10× burst. Support anonymous-to-known identity stitching. Delete one user. Fix a corrupt SDK version. Estimate monthly storage.</div>\n      <a class=\"doc\" href=\"https://cloud.google.com/dataflow/docs/guides/streaming-modes\" target=\"_blank\" rel=\"noopener\">Dataflow streaming modes</a><a class=\"doc\" href=\"https://cloud.google.com/bigquery/docs/partitioned-tables\" target=\"_blank\" rel=\"noopener\">BigQuery partitioning</a>\n    </section>"
  },
  {
    "id": "cdc",
    "title": "CDC to BigQuery",
    "html": "<section class=\"casebook-section\" id=\"case-cdc\">\n      <div class=\"section-head\"><div class=\"num\">02</div><div><h2>Database CDC into BigQuery</h2><p>Replicate operational databases into a governed analytical layer with low source impact.</p></div></div>\n      <div class=\"brief\"><article class=\"card\"><div class=\"tags\"><span class=\"tag\">CDC</span><span class=\"tag amber\">Correctness</span></div><p class=\"question\">“Design near-real-time CDC from 50 databases into BigQuery.”</p><p>Analytics must reflect inserts, updates, and deletes while preserving replay and auditability.</p></article><article class=\"card\"><h3>Architect’s thesis</h3><p>Preserve an immutable change log and derive current state. Source commit position—not arrival time—orders changes.</p></article></div>\n      <div class=\"skeleton\">\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">01</span><h3>Clarify</h3></div><ul><li>Sources, versions, connectivity, and log access.</li><li>Current-state only or full change history?</li><li>DDL/schema changes and table onboarding workflow.</li><li>Deletion semantics and audit retention.</li><li>Authoritative reconciliation source.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">02</span><h3>Quantify</h3></div><ul><li>20 TB historical snapshot.</li><li>100 MB/s peak change volume.</li><li>5k tables; largest table 4 TB.</li><li>5-minute p95 source-to-query freshness.</li><li>10% annual schema growth; 2× change headroom.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">03</span><h3>Guarantees</h3></div><ul><li>At-least-once change capture; deterministic dedupe.</li><li>Per-record ordering from source metadata.</li><li>RPO &lt; 1 minute; RTO &lt; 2 hours.</li><li>Backfill and CDC overlap without missing changes.</li><li>Daily table-level reconciliation.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">04</span><h3>Model</h3></div><ul><li>Key: source system + table + primary key.</li><li>Metadata: transaction/commit position, timestamp, operation.</li><li>Raw changelog is append-only.</li><li>Current table selects latest valid change per key.</li><li>Tombstones represent deletes; schemas are versioned.</li></ul></article>\n        <article class=\"phase full\"><div class=\"phase-head\"><span class=\"badge\">05</span><h3>Design</h3></div><div class=\"diagram\" role=\"img\" aria-label=\"CDC system design\"><div class=\"diagram-title\">Snapshot and log changes converge on one ordered history</div><div class=\"flow\"><div class=\"node source\">OLTP databases<small>logs + snapshot</small></div><div class=\"arrow\">→</div><div class=\"node\">Datastream<small>backfill + CDC</small></div><div class=\"arrow\">→</div><div class=\"node store\">BigQuery raw change log<small>source metadata</small></div><div class=\"arrow\">→</div><div class=\"node\">Dataform / SQL<small>dedupe + merge</small></div><div class=\"arrow\">→</div><div class=\"node serve\">Current + history marts<small>governed access</small></div></div></div><ul><li>Datastream handles supported database log capture and backfill; private connectivity limits exposure.</li><li>Land enough metadata to reconstruct order and deduplicate; never discard source positions during normalization.</li><li>Build current-state and history models separately. Consumers use curated views, not raw CDC payloads.</li><li>Schema service classifies additive, compatible, and breaking changes; quarantine incompatible events without stalling unrelated tables.</li></ul></article>\n        <article class=\"phase full operate\"><div class=\"phase-head\"><span class=\"badge\">06</span><h3>Operate</h3></div><ul><li><strong>Source safety:</strong> monitor replication slot/log retention, CPU, connection count, and backfill throttling.</li><li><strong>Reconciliation:</strong> row/key counts, checksums or sampled hashes, max commit positions, delete counts.</li><li><strong>Recovery:</strong> checkpoint positions; replay raw changes; re-snapshot one table without rebuilding all sources.</li><li><strong>Security:</strong> per-source service accounts, private connectivity, column policy tags, audit logs.</li><li><strong>Cost:</strong> high-frequency <code>MERGE</code> can dominate. Micro-batch by partition/key range and compact history.</li><li><strong>Rollout:</strong> one source family → noncritical tables → critical tables after reconciliation evidence.</li></ul></article>\n      </div>\n      <div class=\"probes\"><strong>Follow-ups:</strong> A table has no primary key. Updates arrive out of order. A primary key changes. The source log is truncated. A 4 TB table must be re-snapshotted.</div>\n      <a class=\"doc\" href=\"https://cloud.google.com/datastream/docs/behavior-overview\" target=\"_blank\" rel=\"noopener\">Datastream behavior</a><a class=\"doc\" href=\"https://cloud.google.com/bigquery/docs/change-data-capture\" target=\"_blank\" rel=\"noopener\">BigQuery CDC</a>\n    </section>"
  },
  {
    "id": "fraud",
    "title": "Real-time fraud",
    "html": "<section class=\"casebook-section\" id=\"case-fraud\">\n      <div class=\"section-head\"><div class=\"num\">03</div><div><h2>Real-time fraud decisioning</h2><p>Design sub-200 ms transaction decisions plus an auditable analytical feedback loop.</p></div></div>\n      <div class=\"brief\"><article class=\"card\"><div class=\"tags\"><span class=\"tag\">Low latency</span><span class=\"tag amber\">ML</span></div><p class=\"question\">“Score card transactions for fraud in real time.”</p><p>A late answer is equivalent to no answer; decisions must remain explainable and replayable.</p></article><article class=\"card\"><h3>Architect’s thesis</h3><p>Keep Pub/Sub and analytical processing off the synchronous decision path. Use them to update features, audit decisions, and retrain.</p></article></div>\n      <div class=\"skeleton\">\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">01</span><h3>Clarify</h3></div><ul><li>Decision actions: approve, decline, step-up.</li><li>False-positive and fraud-loss cost.</li><li>Human review and appeal workflow.</li><li>Regions, residency, and PCI boundary.</li><li>Can the payment service degrade without the model?</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">02</span><h3>Quantify</h3></div><ul><li>100k transactions/s global; 250k peak.</li><li>p99 decision budget: 200 ms end-to-end.</li><li>Feature lookup budget: 20 ms.</li><li>30-day hot behavioral state.</li><li>7-year immutable decision audit.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">03</span><h3>Guarantees</h3></div><ul><li>99.99% decision API availability.</li><li>Idempotent response per transaction ID.</li><li>Features may be eventually consistent; decision record is durable.</li><li>Defined fail-open/fail-closed policy by risk segment.</li><li>Model/rule version attached to every decision.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">04</span><h3>Model</h3></div><ul><li>Transaction key, merchant, device, account token, amount, geo.</li><li>Online features: velocity counts, device/account risk, recent declines.</li><li>Decision: score, rule hits, action, model version, feature timestamp.</li><li>Labels arrive later from chargebacks/reviews.</li><li>Point-in-time correctness for offline training.</li></ul></article>\n        <article class=\"phase full\"><div class=\"phase-head\"><span class=\"badge\">05</span><h3>Design</h3></div><div class=\"diagram\" role=\"img\" aria-label=\"Fraud decisioning design\"><div class=\"diagram-title\">Synchronous decision path above; asynchronous learning path below</div><div class=\"flow\"><div class=\"node source\">Payment service<small>transaction ID</small></div><div class=\"arrow\">→</div><div class=\"node\">Risk API<small>Cloud Run / GKE</small></div><div class=\"arrow\">⇄</div><div class=\"node store\">Online features<small>Bigtable / cache</small></div><div class=\"arrow\">→</div><div class=\"node serve\">Rules + model<small>versioned decision</small></div></div><div class=\"flow\" style=\"margin-top:.55rem\"><div class=\"node source\">Decision + events<small>async publish</small></div><div class=\"arrow\">→</div><div class=\"node\">Pub/Sub + Dataflow<small>feature updates</small></div><div class=\"arrow\">→</div><div class=\"node store\">BigQuery offline store<small>audit + training</small></div><div class=\"arrow\">→</div><div class=\"node serve\">Model pipeline<small>validate + deploy</small></div></div></div><ul><li>Risk API concurrently retrieves features and executes deterministic rules/model with a strict deadline.</li><li>Idempotency store returns the same outcome for payment retries.</li><li>Events update online aggregates asynchronously; BigQuery retains decision, features-as-seen, and later labels.</li><li>Model deployment uses shadow, canary, champion/challenger, and fast rollback.</li></ul></article>\n        <article class=\"phase full operate\"><div class=\"phase-head\"><span class=\"badge\">06</span><h3>Operate</h3></div><ul><li><strong>Degrade:</strong> cached features, simpler rules, or risk-tiered fail-open/closed—approved by business and compliance.</li><li><strong>Observe:</strong> latency percentiles, feature age, decision distribution, model errors, false positives, fraud loss.</li><li><strong>Protect:</strong> circuit breakers, deadline propagation, regional isolation, load shedding.</li><li><strong>Correctness:</strong> capture exact model/rule version and feature timestamps; replay decisions offline without changing historical record.</li><li><strong>Security:</strong> tokenize account data; isolate PCI scope; tightly audit feature and decision access.</li><li><strong>Cost:</strong> provision the online path for peak; batch/offline work must never contend with decision capacity.</li></ul></article>\n      </div>\n      <div class=\"probes\"><strong>Follow-ups:</strong> Feature store is unavailable. Model latency doubles. Active fraud shifts feature distributions. Avoid training/serving skew. Explain a decline to a regulator.</div>\n    </section>"
  },
  {
    "id": "multitenant",
    "title": "Multi-tenant platform",
    "html": "<section class=\"casebook-section\" id=\"case-multitenant\">\n      <div class=\"section-head\"><div class=\"num\">04</div><div><h2>Multi-tenant enterprise data platform</h2><p>Enable hundreds of teams while isolating access, cost, performance, and operational blast radius.</p></div></div>\n      <div class=\"brief\"><article class=\"card\"><div class=\"tags\"><span class=\"tag\">Platform</span><span class=\"tag violet\">Governance</span></div><p class=\"question\">“Design a self-service GCP data platform for 500 teams.”</p><p>Teams need autonomy, but central security, finance, and compliance need control.</p></article><article class=\"card\"><h3>Architect’s thesis</h3><p>Standardize the control plane and paved roads; decentralize domain data ownership and business logic.</p></article></div>\n      <div class=\"skeleton\">\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">01</span><h3>Clarify</h3></div><ul><li>Internal teams or external customers?</li><li>Isolation requirements by data class.</li><li>Approved runtimes and regions.</li><li>Central vs. domain responsibility.</li><li>Chargeback/showback and support model.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">02</span><h3>Quantify</h3></div><ul><li>500 teams; 5k pipelines; 100 PB total.</li><li>20k daily jobs; 2k concurrent queries peak.</li><li>50 new datasets/week.</li><li>Three workload tiers.</li><li>24/7 global use, but region-bound sensitive data.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">03</span><h3>Guarantees</h3></div><ul><li>Tier-1 freshness/availability SLOs; best effort for sandbox.</li><li>No cross-domain access without explicit grant.</li><li>Cost attributable to owner/workload.</li><li>Provisioning within 30 minutes.</li><li>Regional and policy constraints enforced automatically.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">04</span><h3>Model</h3></div><ul><li>Tenant/domain, product, owner, classification, SLO, region.</li><li>Every asset has lifecycle and support tier.</li><li>Projects separate environments and major blast radii.</li><li>Datasets organize product boundaries.</li><li>Contracts describe schema, semantics, quality, consumers.</li></ul></article>\n        <article class=\"phase full\"><div class=\"phase-head\"><span class=\"badge\">05</span><h3>Design</h3></div><div class=\"diagram\" role=\"img\" aria-label=\"Multi-tenant platform design\"><div class=\"diagram-title\">Central control plane; domain-owned data planes</div><div class=\"flow\"><div class=\"node source\">Developer portal<small>request + metadata</small></div><div class=\"arrow\">→</div><div class=\"node\">Platform control plane<small>policy + templates</small></div><div class=\"arrow\">→</div><div class=\"node\">Terraform / CI<small>projects, IAM, budgets</small></div><div class=\"arrow\">→</div><div class=\"node store\">Domain data planes<small>BQ / GCS / Dataflow</small></div><div class=\"arrow\">→</div><div class=\"node serve\">Catalog + observability<small>lineage, SLO, cost</small></div></div></div><ul><li>Portal captures ownership, region, classification, SLO, and cost center, then applies policy-as-code.</li><li>Golden modules create projects/datasets, service identities, CMEK, network boundaries, budgets, logging, and CI.</li><li>Reservations isolate workload classes; domain projects isolate quotas and billing. Shared storage does not imply shared compute.</li><li>Knowledge Catalog exposes products, lineage, glossary, and quality while enforcing metadata access.</li></ul></article>\n        <article class=\"phase full operate\"><div class=\"phase-head\"><span class=\"badge\">06</span><h3>Operate</h3></div><ul><li><strong>Guardrails:</strong> hard controls for exfiltration/IAM/regions; recommendations for style and optimization.</li><li><strong>Adoption:</strong> onboarding funnel, time-to-first-production, support tickets, retained usage, exception rate.</li><li><strong>Noisy neighbor:</strong> reservation assignments, quotas, separate projects, priority classes.</li><li><strong>Reliability:</strong> tiered on-call; platform owns common services, domains own product correctness.</li><li><strong>Cost:</strong> labels and project hierarchy drive showback; idle reservations and storage lifecycle are visible.</li><li><strong>Evolution:</strong> version modules; test upgrades on cohorts; never force all domains to move simultaneously.</li></ul></article>\n      </div>\n      <div class=\"trade\"><table><thead><tr><th>Centralize</th><th>Federate</th><th>Reason</th></tr></thead><tbody><tr><td>Identity, network, encryption, audit</td><td>Business transformations</td><td>Global risk versus domain context</td></tr><tr><td>Provisioning templates</td><td>Data-product roadmaps</td><td>Economy of scale versus local priority</td></tr><tr><td>Catalog primitives</td><td>Glossary stewardship</td><td>Shared discovery versus semantic ownership</td></tr><tr><td>Minimum SLO framework</td><td>Target values and budgets</td><td>Comparable reliability versus business criticality</td></tr></tbody></table></div>\n      <div class=\"probes\"><strong>Follow-ups:</strong> A team needs an exception. One domain causes 40% of cost. Central tooling is down. How do external partners access one product? How do you prevent the platform team becoming a bottleneck?</div>\n    </section>"
  },
  {
    "id": "privacy",
    "title": "Privacy deletion",
    "html": "<section class=\"casebook-section\" id=\"case-privacy\">\n      <div class=\"section-head\"><div class=\"num\">05</div><div><h2>Privacy deletion across the data estate</h2><p>Design a provable subject-deletion workflow across warehouse, lake, derived products, and serving systems.</p></div></div>\n      <div class=\"brief\"><article class=\"card\"><div class=\"tags\"><span class=\"tag\">Privacy</span><span class=\"tag amber\">Governance</span></div><p class=\"question\">“Delete one person’s data everywhere within the policy SLA.”</p><p>Legal/policy defines scope and exceptions; architecture must locate, execute, verify, and prove.</p></article><article class=\"card\"><h3>Architect’s thesis</h3><p>Design for deletion at ingestion: tokenize direct identifiers, maintain a subject locator, and propagate signed deletion commands as idempotent workflows.</p></article></div>\n      <div class=\"skeleton\">\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">01</span><h3>Clarify</h3></div><ul><li>Which identities and jurisdictions are in scope?</li><li>Hard delete, anonymize, restrict, or retain under exception?</li><li>Policy SLA and proof required.</li><li>Backups, logs, ML models, exports, vendors.</li><li>Authority that approves and closes a request.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">02</span><h3>Quantify</h3></div><ul><li>100 PB across 10k assets.</li><li>1M requests/year; 10k/day peak.</li><li>30-day policy SLA; critical stores in 24h.</li><li>Hundreds of external exports.</li><li>Evidence retained per policy.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">03</span><h3>Guarantees</h3></div><ul><li>Authenticated, authorized, immutable request record.</li><li>Idempotent execution per subject + policy version.</li><li>No asset marked complete without verification.</li><li>Retry and resume after partial failure.</li><li>Explicit exceptions and backup expiration—not silent omission.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">04</span><h3>Model</h3></div><ul><li>Canonical subject token separates identity from facts.</li><li>Locator maps subject to assets/partitions/keys.</li><li>Deletion request includes scope, reason, policy, deadline.</li><li>Per-asset task state and verification evidence.</li><li>Lineage expands affected derived products.</li></ul></article>\n        <article class=\"phase full\"><div class=\"phase-head\"><span class=\"badge\">05</span><h3>Design</h3></div><div class=\"diagram\" role=\"img\" aria-label=\"Privacy deletion workflow\"><div class=\"diagram-title\">Request → discover → execute → verify → attest</div><div class=\"flow\"><div class=\"node source\">Privacy intake<small>verified request</small></div><div class=\"arrow\">→</div><div class=\"node\">Workflow controller<small>idempotent state machine</small></div><div class=\"arrow\">⇄</div><div class=\"node store\">Locator + catalog + lineage<small>scope assets</small></div><div class=\"arrow\">→</div><div class=\"node\">Store-specific workers<small>BQ / GCS / Bigtable / SaaS</small></div><div class=\"arrow\">→</div><div class=\"node serve\">Evidence ledger<small>verify + attest</small></div></div></div><ul><li>Tokenization limits where direct identity exists; subject locator avoids scanning the entire lake per request.</li><li>Controller fans out idempotent store-specific tasks, tracks retries, and escalates approaching deadlines.</li><li>BigQuery may use keyed DML/partition rewrites; object stores may rewrite affected objects or use crypto-shredding where the approved data model supports it.</li><li>Downstream lineage creates tasks for derived tables, feature stores, exports, and vendor APIs.</li></ul></article>\n        <article class=\"phase full operate\"><div class=\"phase-head\"><span class=\"badge\">06</span><h3>Operate</h3></div><ul><li><strong>Verify:</strong> independent queries prove absence/anonymization; worker success alone is insufficient.</li><li><strong>Late data:</strong> suppression registry prevents deleted subjects from being reintroduced by replay or delayed events.</li><li><strong>Backups:</strong> record immutable-backup expiry and prevent restore without reapplying deletions.</li><li><strong>Security:</strong> strong requester verification; deletion workers have narrowly scoped, audited permissions.</li><li><strong>Cost:</strong> batch requests by partition/file and design tables around subject-token access where deletion volume justifies it.</li><li><strong>Governance:</strong> legal/privacy owns policy interpretation; engineering owns accurate execution and evidence.</li></ul></article>\n      </div>\n      <div class=\"probes\"><strong>Follow-ups:</strong> Identity is not known in every dataset. A deletion arrives during a backfill. Data trained a model. An export went to a vendor. Backups are immutable.</div>\n      <div class=\"callout\"><strong>Interview caveat:</strong> describe this as a technical control system. Do not invent legal retention rules; explicitly defer scope and exceptions to the organization’s privacy/legal policy.</div>\n    </section>"
  },
  {
    "id": "features",
    "title": "ML feature platform",
    "html": "<section class=\"casebook-section\" id=\"case-features\">\n      <div class=\"section-head\"><div class=\"num\">06</div><div><h2>Online/offline ML feature platform</h2><p>Provide low-latency features for inference and point-in-time-correct datasets for training.</p></div></div>\n      <div class=\"brief\"><article class=\"card\"><div class=\"tags\"><span class=\"tag\">ML platform</span><span class=\"tag violet\">Consistency</span></div><p class=\"question\">“Design a feature platform for fraud, recommendations, and churn.”</p><p>Data scientists need reusable definitions without training/serving skew.</p></article><article class=\"card\"><h3>Architect’s thesis</h3><p>One versioned feature definition should drive offline computation, streaming updates, validation, and online publication.</p></article></div>\n      <div class=\"skeleton\">\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">01</span><h3>Clarify</h3></div><ul><li>Batch, streaming, or request-time features?</li><li>Online latency and availability by use case.</li><li>Feature freshness and historical lookback.</li><li>Entity keys and label timing.</li><li>Who approves feature reuse and sensitive attributes?</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">02</span><h3>Quantify</h3></div><ul><li>5k features; 50M entities.</li><li>1M online reads/s; p99 &lt; 15 ms.</li><li>500k updates/s peak.</li><li>5 PB offline history.</li><li>100 training jobs/day.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">03</span><h3>Guarantees</h3></div><ul><li>Feature value includes event time and computation version.</li><li>Point-in-time joins prevent future leakage.</li><li>Online freshness SLA by feature group.</li><li>Fallback/default policy is explicit.</li><li>Reproducible training dataset from pinned definitions and snapshots.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">04</span><h3>Model</h3></div><ul><li>Entity type/key, feature name/version, value, event time.</li><li>Definition, owner, freshness, TTL, sensitivity.</li><li>Offline history is append/versioned.</li><li>Online store keeps latest accepted value per entity/feature.</li><li>Training set records feature definition and source snapshot.</li></ul></article>\n        <article class=\"phase full\"><div class=\"phase-head\"><span class=\"badge\">05</span><h3>Design</h3></div><div class=\"diagram\" role=\"img\" aria-label=\"ML feature platform\"><div class=\"diagram-title\">Shared definitions feed offline and online planes</div><div class=\"flow\"><div class=\"node source\">Sources<small>events + warehouse</small></div><div class=\"arrow\">→</div><div class=\"node\">Feature definitions<small>versioned registry</small></div><div class=\"arrow\">→</div><div class=\"node\">Dataflow / BigQuery<small>stream + batch compute</small></div><div class=\"arrow\">↙</div><div class=\"node store\">BigQuery offline<small>history + PIT joins</small></div><div class=\"arrow\">↘</div><div class=\"node store\">Bigtable online<small>latest low-latency value</small></div><div class=\"arrow\">→</div><div class=\"node serve\">Training + inference<small>versioned consumers</small></div></div></div><ul><li>Registry stores declarative definitions, owners, keys, TTL, and validation rules.</li><li>Batch pipeline computes historical values; streaming pipeline updates freshness-sensitive features.</li><li>Publication layer validates range, freshness, null rate, and key cardinality before online writes.</li><li>Training-set builder performs point-in-time joins and records a reproducibility manifest.</li></ul></article>\n        <article class=\"phase full operate\"><div class=\"phase-head\"><span class=\"badge\">06</span><h3>Operate</h3></div><ul><li><strong>Skew:</strong> compare online/offline distributions and compute parity on sampled entities.</li><li><strong>Freshness:</strong> per-feature-group age SLO; stale values trigger default or last-known-good policy.</li><li><strong>Hot entities:</strong> distribute keys/caches; avoid features that require unbounded request-time fan-out.</li><li><strong>Backfill:</strong> version definitions and offline outputs; do not overwrite training history invisibly.</li><li><strong>Security:</strong> sensitive features require purpose-bound access; prevent raw PII in online keys.</li><li><strong>Cost:</strong> control feature proliferation, TTL online values, and materialize only features with measured reuse/value.</li></ul></article>\n      </div>\n      <div class=\"probes\"><strong>Follow-ups:</strong> Prevent label leakage. A streaming feature is six hours stale. Recompute a feature definition. Serve features across regions. Decide whether a feature belongs in the shared platform.</div>\n    </section>"
  },
  {
    "id": "metrics",
    "title": "Governed metrics",
    "html": "<section class=\"casebook-section\" id=\"case-metrics\">\n      <div class=\"section-head\"><div class=\"num\">07</div><div><h2>Governed metrics and semantic layer</h2><p>Create consistent business definitions without centralizing every analytical decision.</p></div></div>\n      <div class=\"brief\"><article class=\"card\"><div class=\"tags\"><span class=\"tag\">Analytics</span><span class=\"tag amber\">Semantics</span></div><p class=\"question\">“Finance and Product report three different versions of active customer.”</p><p>Design a metrics platform that is trusted, discoverable, and performant.</p></article><article class=\"card\"><h3>Architect’s thesis</h3><p>Version metric meaning, grain, dimensions, and ownership; compile governed definitions into optimized warehouse queries and caches.</p></article></div>\n      <div class=\"skeleton\">\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">01</span><h3>Clarify</h3></div><ul><li>Which decisions require certified metrics?</li><li>BI tools, notebooks, APIs, and embedded consumers.</li><li>Who owns definitions and approves changes?</li><li>Latency and dimensionality requirements.</li><li>Need row/column security at metric query time?</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">02</span><h3>Quantify</h3></div><ul><li>1k certified metrics; 20k users.</li><li>5k dashboard queries/minute peak.</li><li>Interactive p95 &lt; 3 seconds for common slices.</li><li>Hundreds of dimensions; 5-year history.</li><li>Weekly definition changes.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">03</span><h3>Guarantees</h3></div><ul><li>Same metric version yields same result across tools.</li><li>Data freshness visible with every result.</li><li>Access policy is preserved through aggregates/caches.</li><li>Breaking definition changes are versioned.</li><li>Certified lineage reaches source data and dashboards.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">04</span><h3>Model</h3></div><ul><li>Metric: measure, grain, filters, aggregation, owner.</li><li>Allowed dimensions and join paths.</li><li>Time semantics, currency, late-adjustment policy.</li><li>Version/status: draft, certified, deprecated.</li><li>Tests and sample expected results.</li></ul></article>\n        <article class=\"phase full\"><div class=\"phase-head\"><span class=\"badge\">05</span><h3>Design</h3></div><div class=\"diagram\" role=\"img\" aria-label=\"Governed metrics platform\"><div class=\"diagram-title\">Definitions compile into controlled query plans</div><div class=\"flow\"><div class=\"node source\">Domain models<small>tested BigQuery tables</small></div><div class=\"arrow\">→</div><div class=\"node\">Metric registry<small>definitions + versions</small></div><div class=\"arrow\">→</div><div class=\"node\">Compiler / query API<small>policy + SQL</small></div><div class=\"arrow\">→</div><div class=\"node store\">BigQuery + aggregates<small>reservations / cache</small></div><div class=\"arrow\">→</div><div class=\"node serve\">BI / notebooks / apps<small>same semantics</small></div></div></div><ul><li>Definitions live in version control with owners, review, tests, and deprecation policy.</li><li>Compiler resolves joins and generates parameterized BigQuery SQL while carrying access context.</li><li>Common expensive slices use materialized aggregate tables; workload reservations protect executive reporting.</li><li>Every result exposes definition version, freshness, lineage, and certification status.</li></ul></article>\n        <article class=\"phase full operate\"><div class=\"phase-head\"><span class=\"badge\">06</span><h3>Operate</h3></div><ul><li><strong>Quality:</strong> unit tests for definitions, reconciliation to finance controls, dimensional invariants.</li><li><strong>Change:</strong> impact analysis identifies dashboards and APIs; breaking changes get a migration window.</li><li><strong>Performance:</strong> query-shape telemetry drives aggregate creation, caching, clustering, and reservation sizing.</li><li><strong>Security:</strong> enforce row/column policies at query layer and warehouse; never trust dashboard filters as access control.</li><li><strong>Adoption:</strong> track certified-versus-local metric usage and time to answer common questions.</li><li><strong>Governance:</strong> central team owns framework; domains own business meaning; council resolves cross-domain terms.</li></ul></article>\n      </div>\n      <div class=\"probes\"><strong>Follow-ups:</strong> A definition must change historically. Two domains legitimately need different “customer” meanings. Cache results securely. Support semi-additive inventory. Prevent metric explosion.</div>\n    </section>"
  },
  {
    "id": "migration",
    "title": "Hadoop/Kafka migration",
    "html": "<section class=\"casebook-section\" id=\"case-migration\">\n      <div class=\"section-head\"><div class=\"num\">08</div><div><h2>On-prem Hadoop/Kafka to GCP</h2><p>Migrate a business-critical estate while preserving service, correctness, and organizational momentum.</p></div></div>\n      <div class=\"brief\"><article class=\"card\"><div class=\"tags\"><span class=\"tag\">Migration</span><span class=\"tag violet\">Transformation</span></div><p class=\"question\">“Move 5 PB and 1,000 pipelines to GCP in 18 months.”</p><p>The estate mixes batch Spark, Hive SQL, Kafka streams, custom schedulers, and undocumented consumers.</p></article><article class=\"card\"><h3>Architect’s thesis</h3><p>Build migration patterns and verification mechanisms, not 1,000 bespoke projects. Retire workloads before moving them.</p></article></div>\n      <div class=\"skeleton\">\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">01</span><h3>Clarify</h3></div><ul><li>Business deadline and data-center exit dependency.</li><li>Workload criticality, owners, compliance, and regions.</li><li>Cloud target outcomes beyond relocation.</li><li>Allowed coexistence and network bandwidth.</li><li>Skills, contracts, and operating-model changes.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">02</span><h3>Quantify</h3></div><ul><li>5 PB stored; 200 TB/day processed.</li><li>1,000 pipelines; 150 streaming jobs.</li><li>20k topics/tables; 300 consumers.</li><li>10 Gbps usable transfer link.</li><li>18 months; 40 domain teams.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">03</span><h3>Guarantees</h3></div><ul><li>No Tier-1 cutover without tested rollback.</li><li>Business-result parity within defined tolerances.</li><li>No unowned workloads enter migration.</li><li>Dual-run windows proportional to criticality.</li><li>Legacy spend and risk reduce by dated milestones.</li></ul></article>\n        <article class=\"phase\"><div class=\"phase-head\"><span class=\"badge\">04</span><h3>Model</h3></div><ul><li>Portfolio record: owner, inputs, outputs, SLA, cost, risk.</li><li>Disposition: retire, retain, rehost, replatform, rewrite.</li><li>Pattern: Spark, SQL ELT, Beam streaming, SaaS replacement.</li><li>Dependency graph drives wave order.</li><li>Evidence package stores comparison and signoff.</li></ul></article>\n        <article class=\"phase full\"><div class=\"phase-head\"><span class=\"badge\">05</span><h3>Design</h3></div><div class=\"diagram\" role=\"img\" aria-label=\"Hadoop and Kafka migration\"><div class=\"diagram-title\">Coexistence bridge → landing patterns → validated cutover → decommission</div><div class=\"flow\"><div class=\"node source\">HDFS / Hive / Kafka<small>inventory + telemetry</small></div><div class=\"arrow\">→</div><div class=\"node\">Transfer + bridge<small>GCS / dual publish</small></div><div class=\"arrow\">→</div><div class=\"node\">Migration factory<small>templates + converters</small></div><div class=\"arrow\">→</div><div class=\"node store\">GCP targets<small>BQ / Spark / Dataflow</small></div><div class=\"arrow\">→</div><div class=\"node serve\">Parity + cutover<small>consumer signoff</small></div></div></div><ul><li>Usage telemetry and interviews create the portfolio; delete dead datasets/jobs before transfer.</li><li>Choose a small number of landing patterns: Spark to Managed Spark, Hive SQL to BigQuery/Dataform, Kafka streams to retained Kafka or Pub/Sub/Dataflow based on semantics.</li><li>Coexistence bridge supports controlled dual read/publish; it is time-bounded to avoid becoming permanent architecture.</li><li>Migration factory supplies IaC, connectors, code transforms, parity checks, dashboards, and support.</li></ul></article>\n        <article class=\"phase full operate\"><div class=\"phase-head\"><span class=\"badge\">06</span><h3>Operate</h3></div><ul><li><strong>Waves:</strong> representative low-risk workload → one end-to-end domain → repeatable cohorts → crown jewels.</li><li><strong>Parity:</strong> counts, key sets, aggregates, distributions, freshness, and business-specific invariants.</li><li><strong>Rollback:</strong> source-of-truth pointer and consumer routing; preserve legacy long enough for agreed recovery.</li><li><strong>People:</strong> domain teams own business acceptance; central team owns paved paths and migration telemetry.</li><li><strong>Cost:</strong> dual-run burn is visible; milestones include old capacity removal, contracts ended, and data deleted.</li><li><strong>Risk:</strong> freeze new legacy features after viable patterns exist; exceptions require executive owner and expiry.</li></ul></article>\n      </div>\n      <div class=\"trade\"><table><thead><tr><th>Workload</th><th>Likely target</th><th>When not to use it</th></tr></thead><tbody><tr><td>Existing Spark with limited change</td><td>Managed Service for Apache Spark</td><td>Pure SQL transformation is cheaper/simpler in BigQuery</td></tr><tr><td>Hive warehouse SQL</td><td>BigQuery + Dataform</td><td>Unsupported semantics or tight OSS table-format dependency</td></tr><tr><td>Stateful Kafka/Flink stream</td><td>Dataflow/Beam or managed Kafka/Flink</td><td>Migration risk exceeds operational benefit</td></tr><tr><td>Cold HDFS archive</td><td>Cloud Storage lifecycle tiers</td><td>Interactive access pattern requires warehouse/table format</td></tr></tbody></table></div>\n      <div class=\"probes\"><strong>Follow-ups:</strong> Bandwidth misses the deadline. One workload cannot reach parity. Teams keep adding legacy pipelines. Kafka consumers require offsets. How do you prove savings?</div>\n    </section>"
  },
  {
    "id": "check",
    "title": "Interview checklist",
    "html": "<section class=\"casebook-section\" id=\"case-check\">\n      <div class=\"section-head\"><div class=\"num\">09</div><div><h2>Before you finish any design</h2><p>Use this as a final 60-second audit before the interviewer ends the round.</p></div></div>\n      <ul class=\"checklist\"><li>Business outcome is explicit</li><li>Users and source of truth are named</li><li>Scale math is internally consistent</li><li>Latency and correctness are quantified</li><li>Partition/key strategy is explained</li><li>Schema evolution is covered</li><li>Duplicates and late data are covered</li><li>Backfill/replay has an isolation plan</li><li>Failure modes include dependencies</li><li>Data SLOs exceed “job succeeded”</li><li>Security boundary is explicit</li><li>Region/residency is addressed</li><li>Dominant cost driver is named</li><li>At least one alternative is rejected</li><li>Rollout is phased</li><li>Rollback or exit is credible</li></ul>\n      <div class=\"callout\"><strong>Staff+ close:</strong> summarize the two biggest risks, the first validation milestone, and the metric that would cause you to change the design.</div>\n    </section>"
  }
];
